#!/usr/bin/env node

/**
 * Model Selection Utility
 * Reads Anti-Gravity model status and selects the best model based on quota.
 * Falls back to gemini-flash if all candidates are below threshold.
 * Safe to run from cron - idempotent and quiet when no changes needed.
 */

import { readFileSync } from 'fs';

// Configuration
const THRESHOLD = 20;
const FALLBACK_MODEL = 'google/gemini-3-flash-preview';
const AG_PREFIX = 'google-antigravity/';

// Allowed Anti-Gravity model candidates
const CANDIDATES = [
  'google-antigravity/claude-opus-4-5-thinking',
  'google-antigravity/claude-sonnet-4-5',
  'google-antigravity/claude-sonnet-4-5-thinking',
  'google-antigravity/gemini-3-flash',
  'google-antigravity/gemini-3-pro-high',
  'google-antigravity/gemini-3-pro-low',
  'google-antigravity/gpt-oss-120b-medium'
];

const DEFAULT_STATUS_JSON = 'status.json';
const DEFAULT_STATUS_TXT = 'status.txt';

function parseQuotas(statusText) {
  const usageMap = {};
  const lines = statusText.split('\n');

  for (const cand of CANDIDATES) {
    if (cand.includes('gemini')) {
      usageMap[cand] = 100;
    }
  }

  for (const line of lines) {
    if (line.includes('google-antigravity usage:')) {
      const regex = /([a-zA-Z0-9-.]+) (\d+)% left/g;
      let match;
      while ((match = regex.exec(line)) !== null) {
        let modelName = match[1];
        const percent = parseInt(match[2], 10);

        if (!modelName.startsWith(AG_PREFIX)) {
          modelName = AG_PREFIX + modelName;
        }
        usageMap[modelName] = percent;
      }
    }
  }

  return usageMap;
}

function selectModel(usageMap) {
  let bestModel = null;
  let maxPercent = -1;

  for (const model of CANDIDATES) {
    const p = usageMap[model] !== undefined ? usageMap[model] : 0;
    if (p > maxPercent) {
      maxPercent = p;
      bestModel = model;
    }
  }

  if (bestModel && maxPercent >= THRESHOLD) {
    return { model: bestModel, quota: maxPercent, isFallback: false };
  }

  return { model: FALLBACK_MODEL, quota: maxPercent, isFallback: true };
}

function main() {
  const args = process.argv.slice(2);
  let statusJsonPath = DEFAULT_STATUS_JSON;
  let statusTxtPath = DEFAULT_STATUS_TXT;
  let dryRun = false;
  let verbose = false;
  let outputJson = false;

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--json':
        statusJsonPath = args[++i];
        break;
      case '--text':
        statusTxtPath = args[++i];
        break;
      case '--dry-run':
      case '-n':
        dryRun = true;
        break;
      case '--verbose':
      case '-v':
        verbose = true;
        break;
      case '--output-json':
      case '-o':
        outputJson = true;
        break;
    }
  }

  try {
