    const usageMap = parseQuotas(statusText);
    const result = selectModel(usageMap);

    if (outputJson) {
      console.log(JSON.stringify({
        currentModel,
        selectedModel: result.model,
        quota: result.quota,
        isFallback: result.isFallback,
        threshold: THRESHOLD,
        needsSwitch: currentModel !== result.model
      }, null, 2));
    } else if (dryRun) {
