      }
    } else {
      if (currentModel !== result.model) {
        if (result.isFallback) {
          console.log('[ModelSelect] Critical AG quota (Max: ' + result.quota + '%). Fallback to: ' + result.model);
        } else {
          console.log('[ModelSelect] Switching to: ' + result.model + ' (' + result.quota + '%)');
        }
      } else if (verbose) {
        console.log('[ModelSelect] Healthy: ' + currentModel + ' (' + result.quota + '%)');
      }
    }

    process.exit(0);
  } catch (error) {
    console.error('Error: ' + error.message);
    process.exit(1);
  }
}

main();
